{{{#!php
<?php
/**
 * Install a demo package.
 *
 * @since 2.8.0
 * @since 3.7.0 The `$args` parameter was added, making clearing the update cache optional.
 * @access public
 *
 * @param string $package The full local path or URI of the package.
